class LmdbNativeScopedJoinPolicyParityTest {

	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final Pattern NATIVE_EXECUTION = Pattern.compile("nativeInvocationsActual=[1-9][0-9]*");
	private static final String INDEPENDENT_UNION = """
			SELECT ?s WHERE {
			  VALUES ?s { <urn:s1> <urn:s2> }
			  { { GRAPH ?g { ?s <urn:absent> ?o } } UNION { ?u <urn:pD> ?v } }
			}
			""";
	private static final String SHARED_AND_INDEPENDENT_UNION = """
			SELECT ?s WHERE {
			  VALUES ?s { <urn:s1> <urn:s2> }
			  {
			    { VALUES ?s { <urn:s1> <urn:s2> }
			      ?s <urn:pC> ?o . FILTER EXISTS { ?s <urn:pA> ?z } }
			    UNION { ?u <urn:pD> ?v }
			  }
			}
			""";

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void genericAndNativeExecutionPreserveIndependentlyProvedBags(boolean experimental, @TempDir File directory) {
		String previousNative = System.getProperty(NATIVE_FLAG);
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig().setNativeEvaluationEnabled(true));
		store.setExperimentalQueryOptimizations(experimental);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (RepositoryConnection connection = repository.getConnection()) {
				ValueFactory vf = connection.getValueFactory();
				connection.begin();
				for (int i = 0; i < 16; i++) {
					connection.add(vf.createIRI("urn:data:" + i), vf.createIRI("urn:pD"), vf.createIRI("urn:v:" + i));
				}
				for (String subject : new String[] { "urn:s1", "urn:s2" }) {
					connection.add(vf.createIRI(subject), vf.createIRI("urn:pC"), vf.createIRI("urn:shared"));
					connection.add(vf.createIRI(subject), vf.createIRI("urn:pA"), vf.createIRI("urn:exists"));
				}
				connection.commit();
			}
			assertBags(repository, INDEPENDENT_UNION, expected(repository.getValueFactory(), 16));
			assertBags(repository, SHARED_AND_INDEPENDENT_UNION, expected(repository.getValueFactory(), 17));
		} finally {
			try {
				repository.shutDown();
			} finally {
				if (previousNative == null) {
					System.clearProperty(NATIVE_FLAG);
				} else {
					System.setProperty(NATIVE_FLAG, previousNative);
				}
			}
		}
	}

	private static void assertBags(SailRepository repository, String query, Map<BindingSet, Integer> expected) {
		for (boolean nativeEnabled : new boolean[] { false, true }) {
			System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
			try (RepositoryConnection connection = repository.getConnection()) {
				TupleQuery prepared = connection.prepareTupleQuery(QueryLanguage.SPARQL, query);
				Map<BindingSet, Integer> actual = new HashMap<>();
				try (TupleQueryResult rows = prepared.evaluate()) {
					while (rows.hasNext()) {
						actual.merge(new QueryBindingSet(rows.next()), 1, Integer::sum);
					}
				}
				assertEquals(expected, actual, "native=" + nativeEnabled + "\n" + query);
				String executed = prepared.explain(Explanation.Level.Telemetry).toString();
				if (nativeEnabled) {
					assertTrue(NATIVE_EXECUTION.matcher(executed).find(), executed);
				} else {
					assertFalse(NATIVE_EXECUTION.matcher(executed).find(), executed);
				}
			}
		}
	}

	private static Map<BindingSet, Integer> expected(ValueFactory vf, int multiplicity) {
		Map<BindingSet, Integer> expected = new HashMap<>();
		for (String subject : new String[] { "urn:s1", "urn:s2" }) {
			MapBindingSet row = new MapBindingSet();
			row.addBinding("s", vf.createIRI(subject));
			expected.put(row, multiplicity);
		}
		return expected;
	}
}
